export default function Home() {
  const [districts, setDistricts] = useState<string[]>([])
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    phone: "",
    email: "",
    address: "",
    state: "",
    district: "",
    city: "",
    zip: "",
  })

  // Handle state change
  const handleStateChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const state = e.target.value
    setDistricts(stateDistrictData[state] || [])
    setFormData({ ...formData, state, district: "" })
  }

  // Handle phone input + format
  const handlePhoneChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let value = e.target.value.replace(/\D/g, "")
    if (value.length > 10) value = value.slice(0, 10)

    let formatted = value
    if (value.length > 6) {
      formatted = `(${value.slice(0, 3)})-${value.slice(3, 6)}-${value.slice(
        6
      )}`
    } else if (value.length > 3) {
      formatted = `(${value.slice(0, 3)})-${value.slice(3)}`
    }

    setFormData({ ...formData, phone: formatted })
  }

  // Handle email
  const handleEmailChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, email: e.target.value })
  }

  // Handle other fields
  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>
  ) => {
    setFormData({ ...formData, [e.target.id]: e.target.value })
  }

  // Validation on submit
  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()

    const phoneDigits = formData.phone.replace(/\D/g, "")
    if (phoneDigits.length !== 10) {
      toast.error("Phone number must be 10 digits (format: (123)-456-7890).")
      return
    }

    if (!formData.email.includes("@") || !formData.email.includes(".")) {
      toast.error("Please enter a valid email address.")
      return
    }

    if (!formData.state) {
      toast.error("Please select a state.")
      return
    }
    if (!formData.district) {
      toast.error("Please select a district.")
      return
    }

    toast.success("Form submitted successfully!")
    console.log("Form Submitted ✅", formData)
  }

  return (
    <div>
      <Card className="w-full">
        <div className="flex">
          {/* Left Section - Form */}
          <div className="w-1/2 border-r p-2">
            <CardHeader className="pb-2">
              <CardTitle>Add/Edit the single record Here</CardTitle>
            </CardHeader>

            <CardContent>
              <form className="space-y-4" onSubmit={handleSubmit}>
                <FloatingInput id="firstName" label="First Name" type="text" value={formData.firstName} onChange={handleChange} />
                <FloatingInput id="lastName" label="Last Name" type="text" value={formData.lastName} onChange={handleChange} />
                <FloatingInput id="phone" label="Phone" type="text" value={formData.phone} onChange={handlePhoneChange} />
                <FloatingInput id="email" label="Email" type="email" value={formData.email} onChange={handleEmailChange} />
                <FloatingInput id="address" label="Address" type="text" value={formData.address} onChange={handleChange} />

                <div className="grid grid-cols-2 gap-4">
                  <FloatingSelect id="state" label="State" options={Object.keys(stateDistrictData)} value={formData.state} onChange={handleStateChange} />
                  <FloatingSelect id="district" label="District" options={districts} value={formData.district} onChange={handleChange} />
                  <FloatingInput id="city" label="City" type="text" value={formData.city} onChange={handleChange} />
                  <FloatingInput id="zip" label="Zip" type="text" value={formData.zip} onChange={handleChange} />
                </div>

                <Button type="submit" className="w-full">Submit</Button>
              </form>
            </CardContent>
          </div>

          {/* Right Section - Table */}
          <div className="w-1/2 p-4">
            <CardHeader className="pb-2">
              <CardTitle>Check the List of Records</CardTitle>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Action</TableHead>
                    <TableHead>First Name</TableHead>
                    <TableHead>Last Name</TableHead>
                    <TableHead>Phone</TableHead>
                    <TableHead>Email</TableHead>
                    <TableHead>Address</TableHead>
                    <TableHead>City</TableHead>
                    <TableHead>Zip</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {mockData.map((row, index) => (
                    <TableRow key={index}>
                      <TableCell>
                        <Button size="icon" variant="ghost">
                          <Pencil className="h-4 w-4" />
                        </Button>
                      </TableCell>
                      <TableCell>{row.firstName}</TableCell>
                      <TableCell>{row.lastName}</TableCell>
                      <TableCell>{row.phone}</TableCell>
                      <TableCell>{row.email}</TableCell>
                      <TableCell>{row.address}</TableCell>
                      <TableCell>{row.city}</TableCell>
                      <TableCell>{row.zip}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </div>
        </div>
      </Card>
    </div>
  )
}

function FloatingInput({
  id,
  label,
  type,
  value,
  onChange,
}: {
  id: string
  label: string
  type: string
  value: string
  onChange: (e: React.ChangeEvent<HTMLInputElement>) => void
}) {
  return (
    <div className="relative w-full">
      <input
        type={type}
        id={id}
        value={value}
        onChange={onChange}
        placeholder=" "
        className="peer block w-full rounded-md border border-gray-300 px-3 pt-5 pb-2 text-sm 
                   focus:border-gray-500 focus:ring-0 focus:outline-none"
        required
      />
      <label
        htmlFor={id}
        className="absolute left-3 -top-2 text-gray-500 text-xs px-1 bg-white transition-all
          peer-placeholder-shown:top-4 peer-placeholder-shown:text-gray-400 peer-placeholder-shown:text-base
          peer-focus:-top-2 peer-focus:text-xs peer-focus:text-gray-600"
      >
        {label}
      </label>
    </div>
  )
}

function FloatingSelect({
  id,
  label,
  options,
  value,
  onChange,
}: {
  id: string
  label: string
  options: string[]
  value: string
  onChange: (e: React.ChangeEvent<HTMLSelectElement>) => void
}) {
  return (
    <div className="relative w-full">
      <select
        id={id}
        value={value}
        onChange={onChange}
        className="peer block w-full rounded-md border border-gray-300 px-3 pt-5 pb-2 text-sm 
                   focus:border-gray-500 focus:ring-0 focus:outline-none"
        required
      >
        <option value="">Select {label}</option>
        {options.map((opt) => (
          <option key={opt} value={opt}>
            {opt}
          </option>
        ))}
      </select>
      <label
        htmlFor={id}
        className="absolute left-3 -top-2 text-gray-500 text-xs px-1 bg-white"
      >
        {label}
      </label>
    </div>
  )
}
